import fs from "fs";
import path from "path";
import { RecursiveCharacterTextSplitter } from "@langchain/textsplitters";
import { GoogleGenerativeAIEmbeddings } from "@langchain/google-genai";
import { HNSWLib } from "@langchain/community/vectorstores/hnswlib";
import { Document } from "@langchain/core/documents";

const IGNORE_PATTERNS = [
  "node_modules",
  ".git",
  "dist",
  "build",
  "package-lock.json",
  ".env",
  ".jpg", ".jpeg", ".png", ".gif", ".svg", ".ico", ".mp4"
];

// Determine the active API key for embeddings

const getEmbeddingKey = () => {
  const keysString = process.env.GEMINI_API_KEYS || process.env.GOOGLE_AI_KEY;
  if (!keysString) throw new Error("Missing GEMINI_API_KEYS or GOOGLE_AI_KEY in .env");
  const keys = keysString.split(",").map(k => k.trim()).filter(Boolean);
  return keys[0]; // Embeddings don't natively support withFallbacks, using primary key
};

const getEmbeddingsModel = () => {
  return new GoogleGenerativeAIEmbeddings({
    model: "text-embedding-004", // Use model instead of modelName
    apiKey: getEmbeddingKey(),
    taskType: "RETRIEVAL_DOCUMENT", // force document for both to avoid query 404
  });
};

const VECTOR_STORE_PATH = path.join(process.cwd(), ".vector_store");
let vectorStoreInstance = null;

// File crawler to recursively extract files
export const crawlDirectory = (dirPath, arrayOfFiles = []) => {
  if (!fs.existsSync(dirPath)) return arrayOfFiles;

  const files = fs.readdirSync(dirPath);

  for (const file of files) {
    const fullPath = path.join(dirPath, file);
    const isIgnored = IGNORE_PATTERNS.some((pattern) => fullPath.includes(pattern));

    if (isIgnored) continue;

    if (fs.statSync(fullPath).isDirectory()) {
      arrayOfFiles = crawlDirectory(fullPath, arrayOfFiles);
    } else {
      arrayOfFiles.push(fullPath);
    }
  }
  return arrayOfFiles;
};

// Initialize or Load Vector Store

export const initVectorStore = async (projectDir) => {
  const embeddings = getEmbeddingsModel();

  if (fs.existsSync(VECTOR_STORE_PATH)) {
    console.log("Loading existing vector store from disk...");
    vectorStoreInstance = await HNSWLib.load(VECTOR_STORE_PATH, embeddings);
    return vectorStoreInstance;
  }

  console.log("No existing vector store found. Scanning codebase...");
  const files = crawlDirectory(projectDir);
  const documents = [];

  const splitter = new RecursiveCharacterTextSplitter({
    chunkSize: 800,
    chunkOverlap: 100,
    separators: ["\nclass ", "\nfunction ", "\nconst ", "\nexport ", "\n\n", "\n", " "],
  });

for (const file of files) {
    try {
      const content = fs.readFileSync(file, "utf-8");
      const chunks = await splitter.splitText(content);

      chunks.forEach((chunk, index) => {
        documents.push(
          new Document({
            pageContent: chunk,
            metadata: {
              filePath: file,
              fileName: path.basename(file),
              chunkIndex: index,
            },
          })
        );
      });
    } catch (err) {
      console.warn(`Skipping unreadable file: ${file}`);
    }
  }

if (documents.length > 0) {
    console.log(`Generating embeddings for ${documents.length} chunks...`);
    vectorStoreInstance = await HNSWLib.fromDocuments(documents, embeddings);
    await vectorStoreInstance.save(VECTOR_STORE_PATH);
    console.log("Vector store successfully built and saved.");
  } else {
    console.log("No valid code documents found to embed.");
  }

  return vectorStoreInstance;
};

// Search the codebase

export const searchCode = async (query, k = 4) => {
  if (!vectorStoreInstance) {
    throw new Error("Vector store is not initialized. Call initVectorStore first.");
  }
  const results = await vectorStoreInstance.similaritySearch(query, k);
  return results;
};

// Reindex a specific file (Incremental Update)

export const reindexFile = async (filePath, fileContent) => {
  if (!vectorStoreInstance) {
    throw new Error("Vector store is not initialized.");
  }

  // 1. Delete old chunks associated with this filePath
  // Note: HNSWLib in LangChain JS currently doesn't support selective deletion by metadata natively 
  // without rebuilding or maintaining an external ID mapping. 
  // For a robust production solution, transitioning to ChromaDB or PGVector is recommended.
  // As a workaround for HNSWLib, we use an in-memory document filter strategy or append-only.
  console.log(`Warning: HNSWLib does not support metadata deletion. Appending new chunks for ${filePath}.`);

const splitter = new RecursiveCharacterTextSplitter({
    chunkSize: 800,
    chunkOverlap: 100,
    separators: ["\nclass ", "\nfunction ", "\nconst ", "\nexport ", "\n\n", "\n", " "],
  });

  const chunks = await splitter.splitText(fileContent);
  const newDocuments = chunks.map(
    (chunk, index) =>
      new Document({
        pageContent: chunk,
        metadata: {
          filePath,
          fileName: path.basename(filePath),
          chunkIndex: index,
          updatedAt: Date.now(),
        },
      })
  );

  await vectorStoreInstance.addDocuments(newDocuments);
  await vectorStoreInstance.save(VECTOR_STORE_PATH);

  console.log(`Successfully re-indexed ${filePath} (${newDocuments.length} chunks).`);
};

export const getGeminiPool = () => {
  // Try GEMINI_API_KEYS first, fallback to GOOGLE_AI_KEY (what is currently in .env)
  const keysString = process.env.GEMINI_API_KEYS || process.env.GOOGLE_AI_KEY;
  if (!keysString) {
    throw new Error("Missing GEMINI_API_KEYS or GOOGLE_AI_KEY in .env");
  }

  const keys = keysString.split(",").map(key => key.trim()).filter(Boolean);

  if (keys.length === 0) {
    throw new Error("No valid Gemini API keys found.");
  }

  // Instantiate models for each key
  const models = keys.map(
    (key) =>
      new ChatGoogleGenerativeAI({
        modelName: "gemini-1.5-flash",
        apiKey: key,
        temperature: 0.4,
        maxOutputTokens: 8192,
      })
  );

// If there's only one key, return the model directly without fallbacks
  if (models.length === 1) {
    return models[0];
  }

  // Create a fallback chain: models[0] with fallbacks to the rest
  const fallbackModel = models[0].withFallbacks({
    fallbacks: models.slice(1),
  });

  return fallbackModel;
};

